  ('67bb8752-e103-52a4-9849-8015577d99ab', 'Хатуу, уян хуванцар — Шүд нэмэх', 'Авагддаг хиймэл шүдэлбэр', 'Яаралтай гаргах: 1 хоногт +50% · 3 хоногт +20% нэмэгдэлтэй', 45000, 79) -- DE-32
),
matches AS (
  SELECT service."id" AS "serviceId", matched."id" AS "sourceId"
  FROM "Service" AS service
  CROSS JOIN LATERAL (
    SELECT source."id"
    FROM source
    WHERE service."id" = source."id"
       OR (
         lower(btrim(service."category")) = lower(btrim(source."category"))
         AND lower(btrim(service."name")) = lower(btrim(source."name"))
       )
    ORDER BY (service."id" = source."id") DESC
    LIMIT 1
  ) AS matched
),
updated AS (
  UPDATE "Service" AS service
  SET "price" = source."price",
      "description" = CASE
        WHEN source."description" = '' OR strpos(service."description", source."description") > 0
          THEN service."description"
        ELSE concat_ws(E'\n', nullif(service."description", ''), source."description")
      END
  FROM matches JOIN source ON source."id" = matches."sourceId"
  WHERE service."id" = matches."serviceId"
)
INSERT INTO "Service" ("id", "name", "category", "description", "price", "sortOrder")
SELECT source."id", source."name", source."category", source."description", source."price", source."sortOrder"
FROM source
WHERE NOT EXISTS (SELECT 1 FROM matches WHERE matches."sourceId" = source."id");

COMMIT;
